if size < renvoBackendValueSlotSize {
size = renvoBackendValueSlotSize
}
wordSize := renvoCallWordSize(g, typ)
renvoEmitPushWords(g, offset, size, wordSize, renvoPushStack)
return renvoAlignValue(size, wordSize) / wordSize
