renvoAsmPopTertiary(a)
renvoEmitRuntimeBoundsCheck(g)
renvoAsmCopySecondaryToTertiary(a)
renvoAsmPopPrimary(a)
renvoAsmAddScaledTertiary(a, elemSize)
