consumed := 0
integerCount := 0
floatCount := 0
allInteger := true
abi := renvoLinkStaticOption(g.prog.src, fn.linkMethodEnd, fn.nameStart, "float64") |
renvoLinkStaticOption(g.prog.src, fn.linkMethodEnd, fn.nameStart, "float32")<<8
