func RTGSignedFits(value int64, bits int) bool {
if bits <= 0 {
return false
}
if bits >= 63 {
return true
}
limit := int64(1) << (bits - 1)
return value >= -limit && value < limit
}

func RTGUnsignedFits(value uint64, bits int) bool {
if bits <= 0 {
return false
}
if bits >= 63 {
return true
}
return value < uint64(1)<<bits
}

