if pushed {
end++
}
if load <= 0 || end != len(a.code) {
return false
}
a.code[at] += byte(reg * 8)
if pushed {
renvoTruncBytes(&a.code, len(a.code)-1)
}
a.lastPrimaryLoad = 0
