renvoAsmPushTertiary(a)
renvoAarch64AsmMovRegReg(a, renvoAarch64RegRax, renvoAarch64RegTmp)
renvoAarch64AsmPushReg(a, renvoAarch64RegLr)
renvoAsmCallLabel(a, arenaAllocLabel)
