func renvoWasmPut(out *renvoWasmBuffer, value byte) {
out.lastLocalOp = 0
if out.length >= len(out.data) {
nextLen := len(out.data) * 2
if nextLen < 256 {
nextLen = 256
}
next := make([]byte, nextLen)
copy(next, out.data)
out.data = next
}
out.data[out.length] = value
out.length++
}
func renvoWasmAppendU32(out *renvoWasmBuffer, v int) {
for i := 0; i < 5; i++ {
b := byte(v & 0x7f)
v = v >> 7
if i == 4 {
b = b & 0x0f
renvoWasmPut(out, b)
return
}
if v == 0 {
renvoWasmPut(out, b)
return
}
b = b | 0x80
renvoWasmPut(out, b)
}
return
}
func renvoWasmAppendS32(out *renvoWasmBuffer, v int) {
for {
b := byte(v & 0x7f)
signSet := (b & 0x40) != 0
v = v >> 7
done := false
if v == 0 && !signSet {
done = true
}
if v == -1 && signSet {
done = true
}
if !done {
b = b | 0x80
}
renvoWasmPut(out, b)
if done {
return
}
}
}
